import { NivelGobiernoValue } from '../shared/models/tramite.model';

export type UserRole = 'inversor' | 'ejecutivo' | 'admin';

export interface User {
  id: number;
  name: string;
  email: string;
  email_verified_at: string | null;
  role: UserRole;
  nivelGobierno?: NivelGobiernoValue | null;
  nivel_gobierno?: NivelGobiernoValue | null;
  municipio?: string | null;
  created_at?: string;
}

export function roleLabel(role: UserRole): string {
  switch (role) {
    case 'inversor':
      return 'Inversor';
    case 'ejecutivo':
      return 'Ejecutivo';
    case 'admin':
      return 'Administrador';
  }
}
